: "2026-10-12T04:19:51.241911+00:00"}, {"order_id": "59", "deducted_at": "2026-10-12T04:19:53.876314+00:00"}, {"order_id": "60", "deducted_at": "2026-10-12T04:45:06.244737+00:00"}, {"order_id": "61", "deducted_at": "2026-10-12T05:41:25.877698+00:00"}, {"order_id": "63", "deducted_at": "2026-10-12T05:51:58.256593+00:00"}, {"order_id": "62", "deducted_at": "2026-10-12T05:52:04.793311+00:00"}, {"order_id": "64", "deducted_at": "2026-10-12T06:11:07.100493+00:00"}, {"order_id": "65", "deducted_at": "2026-10-12T06:30:45.611924+00:00"}, {"order_id": "66", "deducted_at": "2026-10-12T06:30:46.842625+00:00"}, {"order_id": "67", "deducted_at": "2026-10-12T07:28:33.514789+00:00"}, {"order_id": "68", "deducted_at": "2026-10-12T07:48:55.808953+00:00"}, {"order_id": "69", "deducted_at": "2026-10-13T03:17:02.656566+00:00"}, {"order_id": "70", "deducted_at": "2026-10-13T03:17:04.283379+00:00"}, {"order_id": "81", "deducted_at": "2026-10-18T14:10:01.825165+00:00"}, {"order_id": "1000000012031", "deducted_at": "2026-10-30T23:54:11.24728+00:00"}, {"order_id": "1000000012033", "deducted_at": "2026-10-31T03:06:48.581832+00:00"}]}, "columns": {"staff": ["auth_user_id", "created_at", "full_name", "id", "is_active", "role_label", "updated_at"], "orders": ["created_at", "created_by", "customer_name", "id", "notes", "order_number", "order_type", "payment_method", "payment_reference_number", "payment_status", "source", "status", "updated_at"], "feedback": ["created_at", "feedback_type", "id", "message", "order_id", "rating", "reviewed_at", "reviewed_by", "status"], "suppliers": ["address", "created_at", "id", "mobile", "name", "product_name", "product_type", "updated_at"], "menu_items": ["brand", "category_id", "created_at", "description", "id", "image_url", "is_active", "is_available", "is_featured", "item_type", "name", "price", "stock_count", "subcategory_id", "updated_at"], "promotions": ["created_at", "ends_at", "id", "is_active", "menu_item_id", "starts_at", "title"], "ingredients": ["ar